/*
 * LupoUsbDriver legacy port: lupousb.library skeleton.
 *
 * StormC built the library automatically ("#pragma libbase" + .fd): romtag,
 * init/open/close/expunge and the jump table. With gcc they are written here.
 * The user functions come, in .fd order, from the table generated by
 * legacy/tools/fdtable.py. The code of the library itself (LupoUsbLibrary.c)
 * is unchanged apart from the mechanical port.
 *
 * SPDX-License-Identifier: MIT
 */
#include <exec/types.h>
#include <exec/resident.h>
#include <exec/libraries.h>
#include <exec/execbase.h>
#include <dos/dosextens.h>
#include <proto/exec.h>

#define REG(r, d) d __asm(#r)

#define LIBNAME  "lupousb.library"
#define VERSION  1
#define REVISION 0
#define VSTRING  "lupousb.library 1.0 (26.11.2026) legacy 2003 code, gcc port"

int _start(void) { return -1; }

struct ExecBase *SysBase;
struct DosLibrary *DOSBase;

struct LupoBase {
    struct Library lib;
    BPTR seglist;
};

extern const void *const lupousb_functable[];   /* generated by fdtable.py */

static const char libname[] = LIBNAME;
static const char idstring[] = VSTRING;

BPTR lib_expunge(REG(a6, struct LupoBase *base));

static struct LupoBase *lib_init(REG(d0, struct LupoBase *base), REG(a0, BPTR seglist),
                                 REG(a6, struct ExecBase *sysbase))
{
    SysBase = sysbase;
    base->seglist = seglist;
    base->lib.lib_Node.ln_Type = NT_LIBRARY;
    base->lib.lib_Node.ln_Name = (char *)libname;
    base->lib.lib_Flags = LIBF_SUMUSED | LIBF_CHANGED;
    base->lib.lib_Version = VERSION;
    base->lib.lib_Revision = REVISION;
    base->lib.lib_IdString = (APTR)idstring;
    DOSBase = (struct DosLibrary *)OpenLibrary((CONST_STRPTR)"dos.library", 37);
    if (!DOSBase) {
        FreeMem((UBYTE *)base - base->lib.lib_NegSize,
                base->lib.lib_NegSize + base->lib.lib_PosSize);
        return NULL;
    }
    return base;
}

struct LupoBase *lib_open(REG(a6, struct LupoBase *base))
{
    base->lib.lib_OpenCnt++;
    base->lib.lib_Flags &= ~LIBF_DELEXP;
    return base;
}

BPTR lib_close(REG(a6, struct LupoBase *base))
{
    if (--base->lib.lib_OpenCnt == 0 && (base->lib.lib_Flags & LIBF_DELEXP))
        return lib_expunge(base);
    return 0;
}

BPTR lib_expunge(REG(a6, struct LupoBase *base))
{
    BPTR seg;
    if (base->lib.lib_OpenCnt) {
        base->lib.lib_Flags |= LIBF_DELEXP;
        return 0;
    }
    seg = base->seglist;
    Remove(&base->lib.lib_Node);
    CloseLibrary((struct Library *)DOSBase);
    FreeMem((UBYTE *)base - base->lib.lib_NegSize, base->lib.lib_NegSize + base->lib.lib_PosSize);
    return seg;
}

ULONG lib_null(void) { return 0; }

static const ULONG inittable[4] = {
    sizeof(struct LupoBase), (ULONG)lupousb_functable, 0, (ULONG)lib_init
};

const struct Resident __attribute__((used)) romtag = {
    RTC_MATCHWORD, (struct Resident *)&romtag, (APTR)(&romtag + 1), RTF_AUTOINIT,
    VERSION, NT_LIBRARY, 0, (char *)libname, (char *)idstring, (APTR)inittable
};
